1	import { notFound } from "next/navigation";
2	import { PORTFOLIO_DETAILS } from "@/lib/constants/portfolio-details";
3	import { createMetadata } from "@/lib/seo/metadata";
4	import { CaseStudyContent } from "@/components/our-works-detail/case-study-content";
5	import { CaseStudyGallery } from "@/components/our-works-detail/case-study-gallery";
6	import layoutStyles from "./case-study-layout.module.css";
7	
8	export function generateStaticParams() {
9	  return PORTFOLIO_DETAILS.map((d) => ({ slug: d.slug }));
10	}
11	
12	export async function generateMetadata({
13	  params,
14	}: {
15	  params: Promise<{ slug: string }>;
16	}) {
17	  const { slug } = await params;
18	  const detail = PORTFOLIO_DETAILS.find((d) => d.slug === slug);
19	  if (!detail) return {};
20	  return createMetadata({
21	    title: `${detail.title} | Case Study | Boldteq`,
22	    description: `${detail.challenge.slice(0, 155)}...`,
23	    path: `/our-works/${detail.slug}`,
24	    ogImage: detail.gallery[0],
25	  });
26	}
27	
28	export default async function CaseStudyPage({
29	  params,
30	}: {
31	  params: Promise<{ slug: string }>;
32	}) {
33	  const { slug } = await params;
34	  const detail = PORTFOLIO_DETAILS.find((d) => d.slug === slug);
35	  if (!detail) notFound();
36	
37	  return (
38	    <section className={layoutStyles.pageOut}>
39	      <div className={layoutStyles.container}>
40	        <div className={layoutStyles.grid}>
41	          <CaseStudyContent detail={detail} />
42	          <CaseStudyGallery images={detail.gallery} title={detail.title} />
43	        </div>
44	      </div>
45	    </section>
46	  );
47	}
