/* ============================================================
   Case Study Layout — matches Webflow work-page-out + work-page-grid
   ============================================================ */

/* section.work-page-out */
.pageOut {
  border-radius: 20px;
  padding: 0;
  overflow: hidden;
}

/* container-large-3 */
.container {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
}

/* div.work-page-grid */
.grid {
  display: grid;
  grid-column-gap: 0;
  grid-row-gap: 0;
  grid-template-rows: auto;
  grid-template-columns: 1.25fr 1fr;
  overflow: hidden;
}

/* ============================================================
   max-width: 991px
   ============================================================ */
@media screen and (max-width: 991px) {
  .grid {
    grid-template-columns: 1.25fr;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .grid {
    grid-template-columns: 1fr;
  }
}

