3	import { useState } from "react";
4	import Image from "next/image";
5	import styles from "./case-study-gallery.module.css";
6	
7	interface CaseStudyGalleryProps {
8	  images: string[];
9	  title: string;
10	}
11	
12	export function CaseStudyGallery({ images, title }: CaseStudyGalleryProps) {
13	  const [activeIndex, setActiveIndex] = useState(0);
14	
15	  if (images.length === 0) return null;
16	
17	  const activeImage = images[activeIndex];
18	
19	  return (
20	    <div className={styles.gallery}>
21	      <div className={styles.galleryWrapper}>
22	        {/* Main image — work-slide (flex: 1) + work-slide-image */}
23	        <div className={styles.mainSlide}>
24	          <Image
25	            src={activeImage}
26	            alt={title}
27	            fill
28	            className={styles.mainImg}
29	            sizes="(max-width: 900px) 100vw, 50vw"
30	            priority
31	          />
32	        </div>
33	
34	        {/* Thumbnails — work-gallery-thumbs */}
35	        {images.length > 1 && (
36	          <div className={styles.thumbnails}>
37	            {images.map((src, index) => (
38	              <button
39	                key={index}
40	                type="button"
41	                className={`${styles.thumb} ${index === activeIndex ? styles.thumbActive : ""}`}
42	                onClick={() => setActiveIndex(index)}
43	                aria-label={`View image ${index + 1} of ${images.length}`}
44	                aria-pressed={index === activeIndex}
45	              >
46	                <Image
47	                  src={src}
48	                  alt={`${title} — image ${index + 1}`}
49	                  fill
50	                  className={styles.thumbImg}
51	                  sizes="(max-width: 900px) 33vw, 16vw"
52	                />
53	              </button>
54	            ))}
55	          </div>
56	        )}
57	      </div>
58	    </div>
59	  );
60	}
