"use client";

import { useState, useMemo } from "react";
import Image from "next/image";
import { BLOG_POSTS, BLOG_CATEGORIES } from "@/lib/constants/blog";
import { BlogCard } from "./blog-card";
import styles from "./blog-grid.module.css";

const CATEGORY_LABELS: Record<string, string> = {
  all: "All",
  cro: "CRO",
  shopify: "Shopify",
  "ui-ux-design": "UI/UX Design",
  "web-development": "Web Development",
  "white-label-outsourcing": "White-Label & Outsourcing",
  wordpress: "WordPress",
};

export function BlogGrid() {
  const [activeCategory, setActiveCategory] = useState<string>("all");
  const [searchQuery, setSearchQuery] = useState<string>("");

  const filtered = useMemo(() => {
    return BLOG_POSTS.filter((post) => {
      const matchesCategory =
        activeCategory === "all" || post.category === activeCategory;
      const normalizedQuery = searchQuery.trim().toLowerCase();
      const matchesSearch =
        normalizedQuery === "" ||
        post.title.toLowerCase().includes(normalizedQuery) ||
        post.shortDescription.toLowerCase().includes(normalizedQuery) ||
        post.category.toLowerCase().includes(normalizedQuery);
      return matchesCategory && matchesSearch;
    });
  }, [activeCategory, searchQuery]);

  const topPosts = useMemo(() => BLOG_POSTS.slice(0, 4), []);

  const handleClearCategory = () => {
    setActiveCategory("all");
  };

  return (
    <section className={styles.section}>
      <div className={styles.tabsContainer}>
        <div className={styles.filtOut}>
          <div className={styles.filterGrid}>
            {/* ── LEFT SIDEBAR ── */}
            <div className={styles.filterColumn}>
              {/* Search */}
              <div className={styles.searchBlock}>
                <input
                  type="search"
                  className={styles.searchField}
                  placeholder="Search here..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  aria-label="Search blog articles"
                />
              </div>

              {/* Categories */}
              <div className={styles.filterBlock}>
                <div className={styles.filterBlockHeader}>
                  <button
                    type="button"
                    className={styles.filterReset}
                    onClick={handleClearCategory}
                    aria-label="Clear category filter"
                  >
                    Clear
                  </button>
                  <h3 className={styles.filterBarTitle}>Categories</h3>
                </div>
                <div className={styles.filterOptions}>
                  <ul className={styles.categoryList} role="list">
                    {BLOG_CATEGORIES.map((cat) => {
                      const isActive = activeCategory === cat.slug;
                      return (
                        <li key={cat.slug} className={styles.categoryItem}>
                          <input
                            type="checkbox"
                            id={`cat-${cat.slug}`}
                            className={styles.categoryCheckbox}
                            checked={isActive}
                            onChange={() =>
                              setActiveCategory(isActive ? "all" : cat.slug)
                            }
                            aria-label={`Filter by ${cat.name}`}
                          />
                          <label
                            htmlFor={`cat-${cat.slug}`}
                            className={`${styles.categoryLabel} ${isActive ? styles.categoryLabelActive : ""}`}
                          >
                            {cat.name}
                          </label>
                        </li>
                      );
                    })}
                  </ul>
                </div>
              </div>

              {/* Top Posts */}
              <div className={styles.filterBlock}>
                <div className={styles.filterBlockHeader}>
                  <span />
                  <h3 className={styles.filterBarTitle}>Top Posts</h3>
                </div>
                <div className={styles.filterOptions}>
                  <ul className={styles.topPostsList} role="list">
                    {topPosts.map((post, index) => (
                      <li key={post.slug} className={styles.topPostItem}>
                        <span
                          className={styles.topPostNumber}
                          aria-hidden="true"
                        >
                          {String(index + 1).padStart(2, "0")}
                        </span>
                        <div className={styles.topPostInner}>
                          <a
                            href={`/blog/${post.slug}`}
                            className={styles.topPostTitle}
                          >
                            {post.title}
                          </a>
                          <p className={styles.topPostCat}>
                            {CATEGORY_LABELS[post.category] ?? post.category}
                          </p>
                        </div>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>

              {/* Follow Us */}
              <div className={styles.filterBlock}>
                <div className={styles.filterBlockHeader}>
                  <span />
                  <h3 className={styles.filterBarTitle}>Follow Us</h3>
                </div>
                <div className={styles.filterOptions}>
                  <div className={styles.socialRow}>
                    <a
                      href="https://www.linkedin.com/company/boldteq"
                      target="_blank"
                      rel="noopener noreferrer"
                      className={styles.socialLink}
                      aria-label="Boldteq on LinkedIn"
                    >
                      <Image
                        src="/images/webflow/ri_linkedin-fill.svg"
                        alt="LinkedIn"
                        width={24}
                        height={24}
                      />
                    </a>
                    <a
                      href="https://www.instagram.com/boldteq/"
                      target="_blank"
                      rel="noopener noreferrer"
                      className={styles.socialLink}
                      aria-label="Boldteq on Instagram"
                    >
                      <Image
                        src="/images/webflow/mdi_instagram.svg"
                        alt="Instagram"
                        width={24}
                        height={24}
                      />
                    </a>
                    <a
                      href="https://www.facebook.com/people/Boldteq-Global-Pvt-Ltd/100070645008632/"
                      target="_blank"
                      rel="noopener noreferrer"
                      className={styles.socialLink}
                      aria-label="Boldteq on Facebook"
                    >
                      <Image
                        src="/images/webflow/basil_facebook-solid.svg"
                        alt="Facebook"
                        width={24}
                        height={24}
                      />
                    </a>
                  </div>
                </div>
              </div>
            </div>

            {/* ── RIGHT CONTENT ── */}
            <div className={styles.filterContent}>
              {filtered.length === 0 ? (
                <div className={styles.emptyState}>
                  <Image
                    src="/images/webflow/Group.svg"
                    alt=""
                    width={80}
                    height={80}
                    className={styles.emptyIcon}
                    aria-hidden="true"
                  />
                  <p className={styles.emptyText}>No results found.</p>
                </div>
              ) : (
                <ul className={styles.grid} role="list">
                  {filtered.map((post) => (
                    <li key={post.slug}>
                      <BlogCard post={post} />
                    </li>
                  ))}
                </ul>
              )}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

/* ============================================================
   BlogCard — blog-card.module.css
   Matches Webflow .content_card-blog + .content_card-block-blog
   ============================================================ */

/* content_card-blog */
.card {
  grid-column-gap: 1rem;
  grid-row-gap: 1rem;
  color: #000;
  background-color: transparent;
  border: 1px solid rgba(33, 207, 255, 0.23);
  border-radius: 20px;
  grid-template-rows: auto;
  grid-template-columns: 1fr;
  grid-auto-columns: 1fr;
  align-items: start;
  width: 100%;
  height: 240px;
  min-height: auto;
  max-height: none;
  padding: 10px;
  text-decoration: none;
  display: grid;
  overflow: hidden;
  transition: box-shadow 0.2s ease;
}

.card:hover {
  box-shadow: 0 4px 20px rgba(9, 34, 69, 0.12);
}

/* cms-link.blog-link → image link area */
.imageLink {
  display: block;
  height: 100%;
  overflow: hidden;
  text-decoration: none;
  border-radius: 15px;
}

/* content_card-image-blog */
.image {
  object-fit: cover;
  border-radius: 15px;
  width: 100%;
  height: 100%;
  display: block;
  transition: transform 0.3s ease;
}

.card:hover .image {
  transform: scale(1.03);
}

/* content_card-block-blog */
.body {
  grid-column-gap: 0.3rem;
  grid-row-gap: 0.3rem;
  grid-template-rows: auto auto;
  grid-template-columns: 1fr;
  grid-auto-columns: 1fr;
  align-content: center;
  place-items: center start;
  margin-top: 10px;
  padding: 0.5rem 0 0;
  display: grid;
}

/* content_card-header */
.header {
  color: #082753;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 20px;
  font-weight: 700;
  line-height: 30px;
  display: flex;
  text-decoration: none;
  width: 100%;
}

/* content_card-title.blog-post-title */
.title {
  color: #082753;
  text-align: left;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 25px;
  font-weight: 700;
  line-height: 35px;
  margin: 0;
  text-decoration: none;
}

/* blog-cat-name */
.category {
  color: transparent;
  background-image: linear-gradient(#21cfff, #019ae6);
  -webkit-background-clip: text;
  background-clip: text;
  text-align: left;
  margin-bottom: 0;
  margin-top: 0;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 14px;
  font-weight: 500;
}

/* paragraph.text-left.blog-desc */
.description {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 1.125rem;
  color: #2b2b2b;
  line-height: 28px;
  text-align: left;
  margin: 4px 0 0;
}

/* a-gulf-book.blog-read-btn */
.readBtn {
  color: #fff;
  width: auto;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 1rem;
  background-color: #111827;
  background-image: url('/images/webflow/Group-46729-2.svg'),
    linear-gradient(90deg, #21cfff, #019ae6);
  background-position: 93%, 0 0;
  background-repeat: no-repeat, repeat;
  background-size: auto, auto;
  border: 2px solid transparent;
  border-radius: 0.75rem;
  justify-content: center;
  align-items: center;
  margin-top: 8px;
  padding: 0.75rem 3rem 0.75rem 1.25rem;
  font-weight: 700;
  line-height: 1.75rem;
  text-decoration: none;
  display: inline-flex;
  box-shadow: 0 0 5px rgba(0, 0, 0, 0.1);
  transition: background-color 0.2s ease;
}

.readBtn:hover {
  background-color: #092245;
  background-image: url('/images/webflow/Group-46729-2.svg');
  background-repeat: no-repeat;
  background-size: auto;
}

/* ============================================================
   min-width: 1280px
   ============================================================ */
@media screen and (min-width: 1280px) {
  .card {
    align-items: start;
    height: 270px;
    min-height: 280px;
  }
}

/* ============================================================
   min-width: 1440px
   ============================================================ */
@media screen and (min-width: 1440px) {
  .card {
    height: 270px;
    min-height: 280px;
  }
}

/* ============================================================
   max-width: 991px
   ============================================================ */
@media screen and (max-width: 991px) {
  .card {
    align-items: start;
    height: 270px;
    min-height: auto;
  }

  .body {
    padding-bottom: 0;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .card {
    min-height: auto;
  }

  .body {
    padding-bottom: 0;
  }
}

/* ============================================================
   max-width: 479px
   ============================================================ */
@media screen and (max-width: 479px) {
  .body {
    padding: 10px 10px 0;
  }

  .card {
    min-height: auto;
  }
}

import Image from "next/image";
import Link from "next/link";
import type { BlogPost } from "@/types/blog";
import styles from "./blog-card.module.css";

const CATEGORY_LABELS: Record<string, string> = {
  cro: "CRO",
  shopify: "Shopify",
  "ui-ux-design": "UI/UX Design",
  "web-development": "Web Development",
  "white-label-outsourcing": "White-Label & Outsourcing",
  wordpress: "WordPress",
};

interface BlogCardProps {
  post: BlogPost;
}

export function BlogCard({ post }: BlogCardProps) {
  const categoryLabel = CATEGORY_LABELS[post.category] ?? post.category;

  return (
    <article className={styles.card}>
      {/* Image area — cms-link.blog-link */}
      <Link href={`/blog/${post.slug}`} className={styles.imageLink} tabIndex={-1} aria-hidden="true">
        <Image
          src={post.image}
          alt={`${post.title} cover`}
          fill
          sizes="(max-width: 767px) 100vw, (max-width: 1280px) 50vw, 33vw"
          className={styles.image}
          loading="lazy"
        />
      </Link>

      {/* content_card-block-blog */}
      <div className={styles.body}>
        {/* content_card-header */}
        <div className={styles.header}>
          <Link href={`/blog/${post.slug}`} style={{ textDecoration: "none", color: "inherit" }}>
            {/* content_card-title.blog-post-title */}
            <h3 className={styles.title}>{post.title}</h3>
            {/* blog-cat-name */}
            <p className={styles.category}>{categoryLabel}</p>
          </Link>
        </div>

        {/* paragraph.text-left.blog-desc */}
        <p className={styles.description}>{post.shortDescription}</p>

        {/* a-gulf-book.blog-read-btn */}
        <Link href={`/blog/${post.slug}`} className={styles.readBtn}>
          Read Article
        </Link>
      </div>
    </article>
  );
}

